using AdDatabase.API.DTOs;using AdDatabase.API.Extensions;using AdDatabase.BLL.Entities;using AdDatabase.BLL.Interfaces;using AdDatabase.BLL.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace AdDatabase.API.Controllers;[ApiController,Route("api/comments")]public class CommentsController(IUnitOfWork uow):ControllerBase{[HttpGet("ad/{adId:int}")]public async Task<IActionResult>ForAd(int adId,CancellationToken ct)=>Ok(ApiResponse<List<Comment>>.Ok(await uow.Comments.ListAsync(x=>x.AdId==adId,ct)));[Authorize,HttpPost]public async Task<IActionResult>Create(CommentDto d,CancellationToken ct){var ad=await uow.Ads.GetByIdAsync(d.AdId,ct)??throw new KeyNotFoundException("Ad not found");var c=new Comment{AdId=d.AdId,UserId=User.UserId(),Body=d.Body.Trim()};await uow.Comments.AddAsync(c,ct);if(ad.UserId!=c.UserId)await uow.Notifications.AddAsync(new Notification{UserId=ad.UserId,Type="Comment",Message=$"New comment on {ad.Title}"},ct);await uow.SaveChangesAsync(ct);return Ok(ApiResponse<Comment>.Ok(c,"Comment added"));}}
